/**
 * The theme options for MUI's createTheme: both colour schemes, in MUI's CSS-variables mode, switched
 * by `data-theme` as the SOLAR tokens are, so `data-theme="dark"` on any element turns a stock
 * MUI component and a SOLAR one to Dark together. The palette stays literal per scheme: MUI
 * derives channels and shades from it, which a var() cannot give. Native colour mode makes
 * theme.alpha() CSS's relative colour, so it works on every SOLAR colour in both schemes; without it,
 * alpha() reads a channel variable MUI defines only for its own colours.
 */
export function createSolarThemeOptions() {
  return {
    cssVariables: {
      colorSchemeSelector: '[data-theme="%s"]',
      nativeColor: true,
    },
    colorSchemes: {
      light: { palette: solarMuiPalette.light },
      dark: { palette: solarMuiPalette.dark },
    },
    breakpoints: { values: solarMuiBreakpoints },
    spacing: solarMuiSpacing,
    transitions: solarMuiTransitions,
    shape: { borderRadius: parseFloat(solarTokens.light['radius.control']) },
    zIndex: solarZIndex,
    typography: { ...solarMuiVariants, ...solarMuiTypography },
    // Stock MUI components drawn from SOLAR recipes (spec/overlay/mui-theme.yaml), and Typography's
    // element for each variant.
    components: {
      ...solarMuiComponents,
      MuiTypography: {
        defaultProps: { variantMapping: solarMuiVariantMapping },
      },
    },
  };
}
